:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #4caf50;
  --accent-hover: #66bb6a;
  --danger: #e53935;
  --box-default: #3a3a55;
  --box-waiting: #fdd835;
  --box-ready: #4caf50;
  --box-too-soon: #e53935;
  --focus: #ffeb3b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c0;
  margin-bottom: 24px;
}

.box {
  background: var(--box-default);
  border-radius: 12px;
  min-height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.6rem;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  transition: background 0.1s ease, transform 0.1s ease;
  margin-bottom: 24px;
  padding: 16px;
  outline: none;
}

.box:hover {
  filter: brightness(1.1);
}

.box:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.box:active {
  transform: scale(0.98);
}

.box.waiting {
  background: var(--box-waiting);
  color: #1e1e2f;
}

.box.ready {
  background: var(--box-ready);
  color: #fff;
}

.box.too-soon {
  background: var(--box-too-soon);
  color: #fff;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 1.1rem;
  padding: 12px 28px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  font-weight: 600;
  transition: background 0.15s ease, transform 0.1s ease;
  min-width: 120px;
}

button:hover {
  background: var(--accent-hover);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
}

button.secondary {
  background: #555570;
}

button.secondary:hover {
  background: #6a6a8a;
}

.stats {
  display: flex;
  justify-content: space-around;
  font-size: 1.1rem;
  color: #b0b0c0;
}

.stats span {
  font-weight: 700;
  color: var(--text);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .box {
    min-height: 140px;
    font-size: 1.3rem;
  }
  button {
    padding: 10px 20px;
    font-size: 1rem;
    min-width: 100px;
  }
}

(function() {
  'use strict';

  const box = document.getElementById('box');
  const message = document.getElementById('message');
  const startBtn = document.getElementById('startBtn');
  const resetBestBtn = document.getElementById('resetBestBtn');
  const lastTimeEl = document.getElementById('lastTime');
  const bestTimeEl = document.getElementById('bestTime');

  let state = 'idle'; // idle, waiting, ready, too-soon, result
  let startTime = 0;
  let timerId = null;
  let bestTime = null;

  // Load best time from localStorage
  try {
    const stored = localStorage.getItem('pixelReactionBest');
    if (stored !== null) {
      bestTime = parseInt(stored, 10);
      if (isNaN(bestTime)) bestTime = null;
    }
  } catch (e) {
    // localStorage not available
  }

  function updateBestDisplay() {
    bestTimeEl.textContent = bestTime !== null ? bestTime + ' ms' : '—';
  }

  function saveBest() {
    try {
      localStorage.setItem('pixelReactionBest', bestTime);
    } catch (e) {
      // ignore
    }
  }

  function resetBox() {
    state = 'idle';
    box.className = 'box';
    message.textContent = 'Press Start';
    if (timerId) {
      clearTimeout(timerId);
      timerId = null;
    }
  }

  function startGame() {
    if (state === 'waiting' || state === 'ready') return;
    resetBox();
    state = 'waiting';
    box.className = 'box waiting';
    message.textContent = 'Wait for green…';
    const delay = 1000 + Math.random() * 4000; // 1–5 seconds
    timerId = setTimeout(() => {
      timerId = null;
      state = 'ready';
      box.className = 'box ready';
      message.textContent = 'Click now!';
      startTime = performance.now();
    }, delay);
  }

  function handleBoxActivation(e) {
    // Prevent double-trigger from click + keydown
    if (e.type === 'keydown') {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
    }

    if (state === 'idle' || state === 'result' || state === 'too-soon') {
      // Clicking the box when idle does nothing; use Start button
      return;
    }

    if (state === 'waiting') {
      // Too soon
      if (timerId) {
        clearTimeout(timerId);
        timerId = null;
      }
      state = 'too-soon';
      box.className = 'box too-soon';
      message.textContent = 'Too soon!';
      return;
    }

    if (state === 'ready') {
      const reaction = Math.round(performance.now() - startTime);
      state = 'result';
      box.className = 'box';
      message.textContent = reaction + ' ms';
      lastTimeEl.textContent = reaction + ' ms';
      if (bestTime === null || reaction < bestTime) {
        bestTime = reaction;
        updateBestDisplay();
        saveBest();
      }
    }
  }

  function resetBest() {
    bestTime = null;
    updateBestDisplay();
    try {
      localStorage.removeItem('pixelReactionBest');
    } catch (e) {
      // ignore
    }
  }

  // Event listeners
  startBtn.addEventListener('click', startGame);
  resetBestBtn.addEventListener('click', resetBest);
  box.addEventListener('click', handleBoxActivation);
  box.addEventListener('keydown', handleBoxActivation);

  // Initialize display
  updateBestDisplay();
})();
